package piglatin

import "strings"

// Sentence translates an English sentence into Pig Latin.
func Sentence(sentence string) string {
	words := strings.Fields(sentence)
	for i, word := range words {
		words[i] = translate(word)
	}
	return strings.Join(words, " ")
}

// translate applies the Pig Latin rules to a single word.
func translate(word string) string {
	// Rule 1: words starting with a vowel, or with "xr" or "yt", just get "ay".
	if isVowel(word[0]) || strings.HasPrefix(word, "xr") || strings.HasPrefix(word, "yt") {
		return word + "ay"
	}

	// Find the leading consonant cluster. "y" counts as a consonant only at the
	// start of a word; after consonants it acts as a vowel (rule 4).
	i := 0
	for i < len(word) && !isVowel(word[i]) && !(word[i] == 'y' && i > 0) {
		i++
	}

	// Rule 3: if the cluster is followed by "qu", move the "qu" along with it.
	if i+1 < len(word) && word[i] == 'q' && word[i+1] == 'u' {
		i += 2
	}

	return word[i:] + word[:i] + "ay"
}

func isVowel(c byte) bool {
	switch c {
	case 'a', 'e', 'i', 'o', 'u':
		return true
	}
	return false
}

